-- PT146-S3-Q11. Batch 13.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT146-S3-Q11$batch13$ AND q.stimulus=$batch13$From 1880 to 2000 Britain’s economy grew fivefold, but emissions of carbon dioxide, a greenhouse gas, were the same on a per capita basis in Britain in 2000 as they were in 1880.$batch13$ AND q.prompt=$batch13$The claims made above are incompatible with which one of the following generalizations?$batch13$ AND q.correct_choice=$batch13$E$batch13$) THEN RAISE EXCEPTION 'Question changed: PT146-S3-Q11'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch13$b86facc4-a85e-4acd-b2a7-fae411fe5c7a$batch13$) <> 2 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch13$b86facc4-a85e-4acd-b2a7-fae411fe5c7a$batch13$) <> 4 THEN RAISE EXCEPTION 'Explanation changed: PT146-S3-Q11'; END IF; END $guard$;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$D$batch13$, $batch13$The facts are about per capita emissions in Britain. Total emissions could still have grown with the population, which fits this generalization. Nothing contradicts it.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT146-S3-Q11$batch13$ AND e.id=$batch13$b86facc4-a85e-4acd-b2a7-fae411fe5c7a$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
